package in.sevasetu.amc.web;
import in.sevasetu.amc.security.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController{
 private final JdbcClient db;private final PasswordEncoder passwords;private final TokenService tokens;public AuthController(JdbcClient db,PasswordEncoder passwords,TokenService tokens){this.db=db;this.passwords=passwords;this.tokens=tokens;}
 public record Login(@NotBlank String username,@NotBlank String password){} public record LoginResponse(String token,String displayName,String role,String tenantName,String domain,String themeKey,String branchName,boolean facebookSocialEnabled,boolean whatsappEnabled,boolean logoAvailable,Set<String> enabledFeatures){}
 @PostMapping("/login") LoginResponse login(@Valid @RequestBody Login login){var row=db.sql("select u.id,u.tenant_id,u.branch_id,u.username,u.display_name,u.role,u.password_hash,coalesce(t.name,'SevaSetu Control') tenant_name,coalesce(t.domain,'PLATFORM') domain,coalesce(t.theme_key,'service-green') theme_key,b.name branch_name,coalesce((select enabled from amcservice.tenant_feature_entitlements f where f.tenant_id=u.tenant_id and f.feature_code='FACEBOOK_SOCIAL'),false) facebook_social_enabled,coalesce((select enabled from amcservice.tenant_feature_entitlements f where f.tenant_id=u.tenant_id and f.feature_code='WHATSAPP'),false) whatsapp_enabled,(t.logo_data is not null) logo_available,coalesce((select string_agg(f.feature_code,',' order by f.feature_code) from amcservice.tenant_feature_entitlements f where f.tenant_id=u.tenant_id and f.enabled),'') enabled_features from amcservice.users u left join amcservice.tenants t on t.id=u.tenant_id left join amcservice.branches b on b.id=u.branch_id where lower(u.username)=lower(:username) and u.active=true and (t.active=true or u.tenant_id is null)").param("username",login.username()).query((rs,n)->new Object[]{rs.getObject("id",UUID.class),rs.getObject("tenant_id",UUID.class),rs.getObject("branch_id",UUID.class),rs.getString("username"),rs.getString("display_name"),rs.getString("role"),rs.getString("password_hash"),rs.getString("tenant_name"),rs.getString("domain"),rs.getString("theme_key"),rs.getString("branch_name"),rs.getBoolean("facebook_social_enabled"),rs.getBoolean("whatsapp_enabled"),rs.getBoolean("logo_available"),rs.getString("enabled_features")}).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));if(!passwords.matches(login.password(),(String)row[6]))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials");var user=new CurrentUser((UUID)row[0],(UUID)row[1],(UUID)row[2],(String)row[3],(String)row[4],(String)row[5]);return new LoginResponse(tokens.issue(user),user.displayName(),user.role(),(String)row[7],(String)row[8],(String)row[9],(String)row[10],(Boolean)row[11],(Boolean)row[12],(Boolean)row[13],features((String)row[14]));}
 private static Set<String> features(String csv){return csv==null||csv.isBlank()?Set.of():new LinkedHashSet<>(Arrays.asList(csv.split(",")));}
 public record PasswordChange(@NotBlank String currentPassword,@Size(min=10)String newPassword){}
 @PostMapping("/change-password") @ResponseStatus(HttpStatus.NO_CONTENT) void changePassword(@AuthenticationPrincipal CurrentUser u,@Valid @RequestBody PasswordChange r){var hash=db.sql("select password_hash from amcservice.users where id=:id and active").param("id",u.userId()).query(String.class).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));if(!passwords.matches(r.currentPassword(),hash))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Current password is incorrect");db.sql("update amcservice.users set password_hash=:hash where id=:id").param("hash",passwords.encode(r.newPassword())).param("id",u.userId()).update();}
}
